    "تسكن أسرة نادر في شقة قريبة من المدرسة. تقع الشقة في الطابق الثاني من مبنى فيه مصعد. تتكون من غرفتين وصالة ومطبخ وحمام، وفي الصالة نافذتان تطلان على حديقة صغيرة.": "audio/book-youth-two-part-one/cb2575dede8d52.mp3",
    "يشترك نادر وأخوه في غرفة واحدة. وضعا سريرين وخزانة ومكتبًا للدراسة، ورتبا الكتب على رفوف لا تعوق الحركة. يتفقان كل مساء على وقت هادئ للمراجعة وعلى إبقاء الممر بين الأثاث خاليًا.": "audio/book-youth-two-part-one/5fdd13b80db025.mp3",
    "في نهاية الأسبوع تساعد الأسرة في تنظيف الشقة وترتيبها. لا تحتاج إلى شراء أشياء كثيرة كي يكون المكان مريحًا؛ فالنظام والضوء والاحترام المتبادل أهم من كبر المساحة. يحب نادر الحي لأن": "audio/book-youth-two-part-one/d2e20e339122e8.mp3",
    "المكتبة ومحطة الحافلات قريبتان، ولأنه يستطيع الذهاب إلى المدرسة مشيًا.": "audio/book-youth-two-part-one/55cf4bd70bbba9.mp3",
    "كَمِ السَّاعَةُ الْآنَ يَا سَامِي؟": "audio/book-youth-two-part-one/94d7fdcbaaa53a.mp3",
    "السَّاعَةُ السَّابِعَةُ وَالنِّصْفُ صَبَاحًا.": "audio/book-youth-two-part-one/184f53f1aa979e.mp3",
    "مَتَى يَبْدَأُ الدَّرْسُ؟": "audio/book-youth-two-part-one/0144661295ced0.mp3",
    "يَبْدَأُ فِي الثَّامِنَةِ وَالرُّبْعِ.": "audio/book-youth-two-part-one/293e7ba51e66fb.mp3",
    "هَلْ نَذْهَبُ إِلَى الْمَعْهَدِ مَشْيًا؟": "audio/book-youth-two-part-one/98eb3e5bd90124.mp3",
    "نَعَمْ، الطَّرِيقُ قَرِيبٌ، وَنَحْتَاجُ إِلَى عَشْرِ دَقَائِقَ.": "audio/book-youth-two-part-one/b5953fef4e468e.mp3",
    "كَمْ يَوْمًا تَدْرُسُ فِي الْأُسْبُوعِ؟": "audio/book-youth-two-part-one/6ff09247e8cebe.mp3",
    "أَدْرُسُ خَمْسَةَ أَيَّامٍ، مِنَ الِاثْنَيْنِ إِلَى الْجُمُعَةِ.": "audio/book-youth-two-part-one/bea2aa3ff0cdbf.mp3",
    "وَمَاذَا تَفْعَلُ بَعْدَ الدَّرْسِ؟": "audio/book-youth-two-part-one/62cbab783e6e5e.mp3",
    "أُرَاجِعُ فِي الْمَكْتَبَةِ، ثُمَّ أَرْجِعُ إِلَى الْبَيْتِ.": "audio/book-youth-two-part-one/2b181f08aacc3c.mp3",
    "سَأَتَعَلَّمُ تَنْظِيمَ وَقْتِي مِثْلَكَ.": "audio/book-youth-two-part-one/63f5e400d5dddf.mp3",
    "لِنَخْرُجْ فِي الْمَوْعِدِ كَيْ نَصِلَ قَبْلَ بِدَايَةِ الدَّرْسِ.": "audio/book-youth-two-part-one/24546ed389b62d.mp3",
    "سَاعَةٌ": "audio/youth/018.mp3",
    "مُنَبِّهٌ": "audio/book-youth-two-part-one/f52c40fbb72ebb.mp3",
    "تَقْوِيمٌ": "audio/book-youth-two-part-one/a44924759b9f59.mp3",
    "كِتَابٌ": "audio/book-youth-two-part-one/624e9793c8e382.mp3",
