    "أَشْ": "audio/letters/13-vowel-3.mp3",
    "تضع رنا خطتها كل مساء في مفكرة صغيرة. تستيقظ في السابعة صباحًا، وتتناول الإفطار، ثم تذهب إلى المعهد القريب. يبدأ درسها في الثامنة والربع وينتهي عند الحادية عشرة.": "audio/book-youth-two-part-one/8584837fb84b10.mp3",
    "تدرس خمسة أيام في الأسبوع، وتخصص بعض الوقت للقراءة بعد الدرس. يوم الثلاثاء تلتقي بصديقتها في المكتبة عند الخامسة والنصف، أما يوم الخميس فتمارس الرياضة مع أختها قبل العشاء.": "audio/book-youth-two-part-one/fab89bf5823aa0.mp3",
    "ذات يوم تغير موعد الحافلة، فنظرت رنا إلى جدول المواعيد واختارت رحلة أبكر. وصلت دون استعجال، وتعلمت أن الخطة الجيدة تحتاج إلى مرونة. لا تملأ رنا كل ساعة بعمل؛ بل تترك وقتًا للراحة": "audio/book-youth-two-part-one/b22b5908e0113b.mp3",
    "ولزيارة الأسرة. وفي نهاية الأسبوع تراجع ما أنجزته وتختار ما تريد تحسينه في الأيام التالية.": "audio/book-youth-two-part-one/97cfcbc07113a3.mp3",
    "مَتَى تَسْتَيْقِظُ يَا طَارِقُ فِي أَيَّامِ الدِّرَاسَةِ؟": "audio/book-youth-two-part-one/d0071a0200c10e.mp3",
    "أَسْتَيْقِظُ فِي السَّادِسَةِ وَالرُّبْعِ. وَأَنْتِ؟": "audio/book-youth-two-part-one/b3ab7efeb20f43.mp3",
    "أَسْتَيْقِظُ فِي السَّادِسَةِ وَالنِّصْفِ. مَاذَا تَفْعَلُ بَعْدَ ذَلِكَ؟": "audio/book-youth-two-part-one/1ef5c6455744f8.mp3",
    "أُنَظِّفُ أَسْنَانِي وَأَلْبَسُ مَلَابِسِي، ثُمَّ أَتَنَاوَلُ الْفُطُورَ.": "audio/book-youth-two-part-one/c7911f447aaf46.mp3",
    "وَمَتَى تَخْرُجُ إِلَى الْمَعْهَدِ؟": "audio/book-youth-two-part-one/22ec93124c71fc.mp3",
    "أَخْرُجُ فِي السَّابِعَةِ وَالنِّصْفِ، وَأَمْشِي مَعَ أَخِي.": "audio/book-youth-two-part-one/ad23e6dd5d5dba.mp3",
    "هَلْ تَتَغَدَّى فِي الْمَطْعَمِ؟": "audio/book-youth-two-part-one/61a64de26f00c7.mp3",
    "لَا، أَتَغَدَّى فِي الْبَيْتِ عِنْدَ السَّاعَةِ الثَّانِيَةِ بَعْدَ الظُّهْرِ.": "audio/book-youth-two-part-one/d3eeae24f6246b.mp3",
    "مَاذَا تَفْعَلُ فِي الْمَسَاءِ؟": "audio/book-youth-two-part-one/152b47ff663442.mp3",
    "أَقْرَأُ نِصْفَ سَاعَةٍ، وَأُسَاعِدُ فِي تَرْتِيبِ الْمَطْبَخِ، ثُمَّ أَنَامُ فِي الْعَاشِرَةِ.": "audio/book-youth-two-part-one/410aad64d2ea54.mp3",
    "أُرَتِّبُ حَقِيبَتِي قَبْلَ النَّوْمِ كَيْ أَخْرُجَ بِهُدُوءٍ صَبَاحًا.": "audio/book-youth-two-part-one/5e8c155a6b7968.mp3",
    "فِكْرَةٌ جَيِّدَةٌ. تَنْظِيمُ الْوَقْتِ يَجْعَلُ صَبَاحَنَا أَسْهَلَ.": "audio/book-youth-two-part-one/a02f42d6786ae0.mp3",
    "يَسْتَيْقِظُ": "audio/book-youth-two-part-one/34def24a3d8cb7.mp3",
