    "تَسْتَيْقِظُ لَيَانُ فِي السَّادِسَةِ وَالنِّصْفِ صَبَاحًا، فَتَفْتَحُ النَّافِذَةَ وَتُنَظِّفُ أَسْنَانَهَا. لَا تُسْرِعُ إِلَى الْهَاتِفِ؛ تَبْدَأُ يَوْمَهَا بِهُدُوءٍ": "audio/book-youth-two-part-one/0f40235f341699.mp3",
    "وَتُنَظِّمُ وَقْتَهَا.": "audio/book-youth-two-part-one/4c8dd43c328f63.mp3",
    "تَتَنَاوَلُ فُطُورًا بَسِيطًا مَعَ أُسْرَتِهَا، ثُمَّ تَضَعُ الْمَاءَ وَكِتَابَ الْعَرَبِيَّةِ فِي حَقِيبَتِهَا. يَحْمِلُ أَخُوهَا الْأَطْبَاقَ إِلَى الْمَطْبَخِ، وَتَمْسَحُ هِيَ": "audio/book-youth-two-part-one/60163570774aff.mp3",
    "الطَّاوِلَةَ.": "audio/book-youth-two-part-one/51e31d66fd6902.mp3",
    "تُغَادِرُ الْبَيْتَ فِي السَّابِعَةِ وَالرُّبْعِ، وَتَذْهَبُ إِلَى الْمَعْهَدِ بِالْحَافِلَةِ. تَسْتَغْرِقُ الرِّحْلَةُ رُبْعَ سَاعَةٍ، وَتَبْدَأُ الدُّرُوسُ فِي الثَّامِنَةِ.": "audio/book-youth-two-part-one/f509ec736048fe.mp3",
    "بَعْدَ الدُّرُوسِ تَعُودُ إِلَى الْبَيْتِ وَتَسْتَرِيحُ قَلِيلًا، ثُمَّ تُسَاعِدُ أَخَاهَا فِي تَرْتِيبِ الْغُرْفَةِ. يَتَقَاسَمَانِ الْعَمَلَ لِيَنْتَهِيَا مُبَكِّرًا وَيَجِدَا": "audio/book-youth-two-part-one/2b623cdac25ce1.mp3",
    "وَقْتًا لِلرَّاحَةِ.": "audio/book-youth-two-part-one/93a612954e91d4.mp3",
    "فِي الْمَسَاءِ تَقْرَأُ غَالِبًا قِصَّةً قَصِيرَةً، وَتَسْتَمِعُ فِي بَعْضِ الْأَحْيَانِ إِلَى بَرْنَامَجٍ ثَقَافِيٍّ. وَتُجَهِّزُ حَقِيبَتَهَا لِيَوْمِهَا التَّالِي قَبْلَ": "audio/book-youth-two-part-one/4a113df79ff631.mp3",
    "النَّوْمِ.": "audio/book-youth-two-part-one/fb7574fd30b947.mp3",
    "تَنَامُ لَيَانُ فِي الْعَاشِرَةِ لِأَنَّهَا تُحِبُّ أَنْ تَبْدَأَ الصَّبَاحَ بِنَشَاطٍ. لَا تَتَشَابَهُ كُلُّ أَيَّامِهَا، لَكِنَّهَا تُحَاوِلُ الْمُوَازَنَةَ بَيْنَ الدِّرَاسَةِ": "audio/book-youth-two-part-one/b11d6e923ae1d8.mp3",
    "وَالْعَمَلِ وَالرَّاحَةِ.": "audio/book-youth-two-part-one/5aa35cfc115700.mp3",
    "مَاذَا تَدْرُسُ يَا فَارِسُ؟": "audio/book-youth-two-part-one/9d0d29e4344d57.mp3",
    "أَدْرُسُ الْهَنْدَسَةَ، وَأُحِبُّ تَصْمِيمَ الْبُيُوتِ.": "audio/book-youth-two-part-one/313df7bae0cddf.mp3",
    "مَاذَا سَتَعْمَلُ بَعْدَ الدِّرَاسَةِ؟": "audio/book-youth-two-part-one/097ff7265afc10.mp3",
    "سَأَعْمَلُ مُهَنْدِسًا فِي مَكْتَبٍ لِلتَّصْمِيمِ إِذَا تَوَفَّرَتِ الْفُرْصَةُ.": "audio/book-youth-two-part-one/c63cbc40d3d2e9.mp3",
    "هَلْ تَحْتَاجُ إِلَى التَّدْرِيبِ أَوَّلًا؟": "audio/book-youth-two-part-one/a1373a94cd5d79.mp3",
    "نَعَمْ، سَأَتَدَرَّبُ مَعَ فَرِيقٍ ذِي خِبْرَةٍ.": "audio/book-youth-two-part-one/3fa2437e83fd15.mp3",
    "أَنَا أَدْرُسُ الصَّيْدَلَةَ، وَأُرِيدُ أَنْ أَكُونَ صَيْدَلَانِيَّةً.": "audio/book-youth-two-part-one/93285eb4088e4a.mp3",
    "أَيْنَ تَرْغَبِينَ فِي الْعَمَلِ؟": "audio/book-youth-two-part-one/28e5f3fab73411.mp3",
    "فِي صَيْدَلِيَّةٍ أَوْ مُسْتَشْفًى، وَأُحِبُّ مُسَاعَدَةَ النَّاسِ.": "audio/book-youth-two-part-one/b49c9e2adb1944.mp3",
    "كُلُّ مِهْنَةٍ تَحْتَاجُ إِلَى عِلْمٍ وَتَعَاوُنٍ وَأَمَانَةٍ.": "audio/book-youth-two-part-one/b36ce92d9ac227.mp3",
    "صَحِيحٌ. وَسَأَتَعَلَّمُ مِنْ أَصْحَابِ الْخِبْرَةِ بِاسْتِمْرَارٍ.": "audio/book-youth-two-part-one/c89b16e0a8c76d.mp3",
    "أَتَمَنَّى لَكِ النَّجَاحَ فِي دِرَاسَتِكِ وَعَمَلِكِ.": "audio/book-youth-two-part-one/54e2fc1b20bacb.mp3",
